from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_root(my_header: str = Header(None)):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_accepted():
    # By default convert_underscores=True. 
    # If we send 'my_header', it should NOT be accepted if the problem statement is correct.
    # But currently it might be accepted.
    response = client.get("/", headers={"my_header": "value"})
    print(f"Response with my_header: {response.json()}")
    assert response.json()["my_header"] is None

def test_hyphen_header_accepted():
    # If we send 'my-header', it SHOULD be accepted.
    response = client.get("/", headers={"my-header": "value"})
    print(f"Response with my-header: {response.json()}")
    assert response.json()["my_header"] == "value"

def test_underscore_header_accepted_when_convert_underscores_false():
    # If convert_underscores=False, then 'my_header' SHOULD be accepted.
    @app.get("/false")
    async def read_root_false(my_header: str = Header(None, convert_underscores=False)):
        return {"my_header": my_header}

    response = client.get("/false", headers={"my_header": "value"})
    print(f"Response with my_header (convert_underscores=False): {response.json()}")
    assert response.json()["my_header"] == "value"

if __name__ == "__main__":
    try:
        test_underscore_header_accepted()
        print("test_underscore_header_accepted passed")
    except AssertionError as e:
        print("test_underscore_header_accepted failed")

    try:
        test_hyphen_header_accepted()
        print("test_hyphen_header_accepted passed")
    except AssertionError as e:
        print("test_hyphen_header_accepted failed")

    try:
        test_underscore_header_accepted_when_convert_underscores_false()
        print("test_underscore_header_accepted_when_convert_underscores_false passed")
    except AssertionError as e:
        print("test_underscore_header_accepted_when_convert_underscores_false failed")

